// The original launcher used density-specific PNGs. Keep those exact files
// rather than the Unity placeholder/adaptive foreground supplied by export.
private static void ApplyOriginalAndroidIcon(string export)
{
    string source=Path.GetFullPath(Path.Combine(Application.dataPath,"../../AndroidGameIcon/res"));
    string destination=Path.Combine(export,"launcher/src/main/res");
    foreach(string density in new[]{"ldpi","mdpi","hdpi","xhdpi","xxhdpi","xxxhdpi"})
    {
        string directory=Path.Combine(destination,"mipmap-"+density);Directory.CreateDirectory(directory);
        File.Copy(Path.Combine(source,"mipmap-"+density+"/app_icon.png"),Path.Combine(directory,"app_icon.png"),true);
    }
    foreach(string name in new[]{"app_icon.xml","app_icon_round.xml"})
    {
        string generated=Path.Combine(destination,"mipmap-anydpi-v26",name);
        if(File.Exists(generated))File.Delete(generated);
    }
    Debug.Log("BNSM_ORIGINAL_ANDROID_ICON copied six original PNGs; Unity adaptive placeholder removed");
}

