    Intent intent=new Intent(action).addCategory(Intent.CATEGORY_OPENABLE).setType(type);
    // Some vendor pickers filter ZIP files out of recent results. Prefer the system document provider.
    for(String name:new String[]{"com.google.android.documentsui","com.android.documentsui"}) {
