private static int insetLeft,insetTop,insetRight,insetBottom;
private static boolean dockRight=true;
private static float dockFraction=.16f;
private static int dp(Activity activity,float value) { return Math.round(value*activity.getResources().getDisplayMetrics().density); }
private static View viewport(Activity activity) { return activity.getWindow().getDecorView(); }
private static void readInsets(Activity activity) {
    WindowInsets insets=viewport(activity).getRootWindowInsets();if(insets==null)return;
    insetLeft=insets.getSystemWindowInsetLeft();insetTop=insets.getSystemWindowInsetTop();
    insetRight=insets.getSystemWindowInsetRight();insetBottom=insets.getSystemWindowInsetBottom();
    if(Build.VERSION.SDK_INT>=28&&insets.getDisplayCutout()!=null) {
        insetLeft=Math.max(insetLeft,insets.getDisplayCutout().getSafeInsetLeft());
        insetTop=Math.max(insetTop,insets.getDisplayCutout().getSafeInsetTop());
        insetRight=Math.max(insetRight,insets.getDisplayCutout().getSafeInsetRight());
        insetBottom=Math.max(insetBottom,insets.getDisplayCutout().getSafeInsetBottom());
    }
}
private static void moveEntry(int x,int y) {
    popupX=x;popupY=y;
    if(floating!=null&&floating.isShowing())floating.update(x,y,-1,-1);
}
private static void placeEntry(Activity activity,boolean animate) {
    if(floating==null||!floating.isShowing())return;
    readInsets(activity);View parent=viewport(activity);int gap=dp(activity,4);
    int minX=insetLeft+gap,maxX=Math.max(minX,parent.getWidth()-insetRight-entryWidth-gap);
    int minY=insetTop+gap,maxY=Math.max(minY,parent.getHeight()-insetBottom-entryHeight-gap);
    int x=dockRight?maxX:minX,y=minY+Math.round(Math.max(0,Math.min(1,dockFraction))*(maxY-minY));
    if(docking!=null)docking.cancel();
    if(animate) {
        final int fromX=popupX,fromY=popupY,toX=x,toY=y;
        docking=android.animation.ValueAnimator.ofFloat(0,1);docking.setDuration(180);
        docking.addUpdateListener(a->{float f=(float)a.getAnimatedValue();moveEntry(Math.round(fromX+(toX-fromX)*f),Math.round(fromY+(toY-fromY)*f));});docking.start();
    } else moveEntry(x,y);
}
private static void movableEntry(Activity activity) {
    android.content.SharedPreferences prefs=activity.getSharedPreferences("embedded-console",Context.MODE_PRIVATE);
    dockRight=prefs.getBoolean("right",true);dockFraction=prefs.getFloat("heightFraction",.16f);
    final int slop=ViewConfiguration.get(activity).getScaledTouchSlop();
    entry.setOnTouchListener(new View.OnTouchListener(){
        float downX,downY;int startX,startY;boolean moved;
        public boolean onTouch(View view,MotionEvent event){
            if(event.getActionMasked()==MotionEvent.ACTION_DOWN){
                if(docking!=null)docking.cancel();downX=event.getRawX();downY=event.getRawY();startX=popupX;startY=popupY;moved=false;return true;
            }
            if(event.getActionMasked()==MotionEvent.ACTION_MOVE){
                float dx=event.getRawX()-downX,dy=event.getRawY()-downY;
                if(Math.hypot(dx,dy)>slop)moved=true;
                if(moved){View parent=viewport(activity);int gap=dp(activity,4);
                    int x=Math.max(insetLeft+gap,Math.min(parent.getWidth()-insetRight-entryWidth-gap,Math.round(startX+dx)));
                    int y=Math.max(insetTop+gap,Math.min(parent.getHeight()-insetBottom-entryHeight-gap,Math.round(startY+dy)));
                    moveEntry(x,y);
                }return true;
            }
            if(event.getActionMasked()==MotionEvent.ACTION_UP||event.getActionMasked()==MotionEvent.ACTION_CANCEL){
                if(moved){View parent=viewport(activity);int gap=dp(activity,4);
                    dockRight=popupX+entryWidth/2f>=parent.getWidth()/2f;
                    float range=Math.max(1,parent.getHeight()-insetTop-insetBottom-entryHeight-2*gap);
                    dockFraction=Math.max(0,Math.min(1,(popupY-insetTop-gap)/range));
                    prefs.edit().putBoolean("right",dockRight).putFloat("heightFraction",dockFraction).apply();placeEntry(activity,true);
                }else if(event.getActionMasked()==MotionEvent.ACTION_UP)view.performClick();
                return true;
            }return false;
        }
    });
    viewport(activity).addOnLayoutChangeListener((v,l,t,r,b,oldL,oldT,oldR,oldB)->{if(r-l!=oldR-oldL||b-t!=oldB-oldT)placeEntry(activity,false);});
}
