    exports.execute(()->{File source=path==null||path.isEmpty()?null:new File(path);boolean owned=false;try{
        if(source!=null&&(!source.getCanonicalFile().getParentFile().equals(activity.getCacheDir().getCanonicalFile())||!source.getName().matches("embedded-save-[a-f0-9]{32}\\.bnsm-save\\.zip")))throw new IOException("导出路径无效");
        owned=source!=null;File bundle=new SharedWorkspace(activity.getFilesDir(),activity.getExternalFilesDir(null)).bundle(source,runtimeDetails,omission,snapshotMs);
