private void SetCardFace(CardData cardData, int skinId, bool gray)
{
	if (LocalRegisteredCards.CardFacePath(cardData, skinId) != null)
	{
		if (FramedPortrait == null)
		{
			var holder = NGUITools.AddChild(coIllust.gameObject);
			holder.name = "FramedPortrait";
			FramedPortrait = holder.AddComponent<UITexture>();
		}
		FramedPortrait.gameObject.SetActive(true);
		SetPortraitSelected(false);
		FramedPortrait.pivot = coIllust.pivot;
		FramedPortrait.transform.localPosition = Vector3.zero;
		FramedPortrait.depth = coIllust.depth;
		FramedPortrait.shader = Shader.Find(gray ? "DTO-DISCOLOR/Grayscale" : "Unlit/Transparent Colored");
		if (LocalRegisteredCards.ApplyPortrait(FramedPortrait, cardData, skinId, LocalRegisteredCards.PortraitFrame))
		{
			coIllust.enabled = false;
			return;
		}
	}
	if (FramedPortrait != null) HideRegisteredPortrait();
	coIllust.enabled = true;
	coIllust.dynamicMainTextureName = cardData.GetCropCardImageName(skinId);
	CardLayout layout = Singleton<DataTable>.Instance.GetCardLayout(cardData, skinId);
