internal Rect? PortraitBounds { get; private set; }

private Rect? portraitArea;
private float portraitSourceAspect;
private float portraitAlignment;
private Rect portraitSource;
private bool portraitCover;
private bool portraitFade;
private float portraitWidgetAspect;

internal void FitPortrait(Rect area, float sourceAspect, float verticalAlignment)
{
	portraitArea = area;
	portraitSourceAspect = sourceAspect;
	portraitAlignment = verticalAlignment;
	portraitWidgetAspect = 0f;
	portraitCover = portraitFade = false;
	UpdatePortraitBounds();
}

internal void ClearPortraitFit()
{
	portraitArea = null;
	portraitCover = portraitFade = false;
	SetPortraitFade(false);
	if (!PortraitBounds.HasValue) return;
	PortraitBounds = null;
	MarkAsChanged();
}

internal void CoverPortrait(Rect area, Rect source, float sourceAspect, bool fade)
{
	portraitArea = area;
	portraitSource = source;
	portraitSourceAspect = sourceAspect;
	portraitCover = true;
	portraitFade = fade;
	portraitWidgetAspect = 0f;
	UpdatePortraitBounds();
}

internal void SetPortraitFade(bool fade)
{
	if (fade)
	{
		var effect = Shader.Find("Local/HongCardForeground");
		if (effect == null) return;
		material.shader = effect;
		Rect crop = uvRect;
		material.SetVector("_PortraitCrop", new Vector4(crop.x, crop.y, 1f / crop.width, 1f / crop.height));
	}
	else if (material != null && material.shader.name == "Local/HongCardForeground")
	{
		material.shader = LocalOriginalCardAssets.PortraitShader(mainTexture, shader);
	}
}

public override void Update()
{
	base.Update();
	if (portraitArea.HasValue) UpdatePortraitBounds();
}

private void UpdatePortraitBounds()
{
	Rect area = portraitArea.Value;
	Vector3 scale = transform.lossyScale;
	float aspect = Mathf.Abs(scale.y) > .00001f ? Mathf.Abs(scale.x / scale.y) : 0f;
	if (aspect < .00001f || float.IsInfinity(aspect) || float.IsNaN(aspect)) return;
	if (Mathf.Abs(aspect - portraitWidgetAspect) < .0001f) return;
	portraitWidgetAspect = aspect;
	float fit = portraitSourceAspect / aspect;
	Rect bounds;
	if (portraitCover)
	{
		float target = area.width / area.height;
		float width = portraitSource.width * Mathf.Min(1f, target / fit);
		float height = portraitSource.height * Mathf.Min(1f, fit / target);
		uvRect = new Rect(portraitSource.center.x - width / 2f, portraitSource.yMax - height, width, height);
		if (portraitFade) SetPortraitFade(true);
		bounds = area;
	}
	else
	{
		float width = Mathf.Min(area.width, area.height * fit);
		float height = Mathf.Min(area.height, area.width / fit);
		bounds = new Rect(area.center.x - width / 2f,
			area.yMin + (area.height - height) * portraitAlignment, width, height);
	}
	if (PortraitBounds is Rect current && Mathf.Abs(current.width - bounds.width) < .0001f &&
		Mathf.Abs(current.height - bounds.height) < .0001f && Mathf.Abs(current.x - bounds.x) < .0001f &&
		Mathf.Abs(current.y - bounds.y) < .0001f) return;
	PortraitBounds = bounds;
	MarkAsChanged();
}
				material.shader = LocalOriginalCardAssets.PortraitShader(mainTexture,value);
				mDynamicMat = new Material(LocalOriginalCardAssets.PortraitShader(mainTexture,mShader));
		mMatLocalizedLink.Asset.shader = LocalOriginalCardAssets.PortraitShader(value,shader);
	if (PortraitBounds is Rect fitted)
	{
		verts.Add(new Vector3(fitted.xMax, fitted.yMax - 1f, 0f));
		verts.Add(new Vector3(fitted.xMax, fitted.yMin - 1f, 0f));
		verts.Add(new Vector3(fitted.xMin, fitted.yMin - 1f, 0f));
		verts.Add(new Vector3(fitted.xMin, fitted.yMax - 1f, 0f));
	}
	else
	{
		verts.Add(new Vector3(1f - mOffsetRT.x, mOffsetRT.y, 0f));
		verts.Add(new Vector3(1f - mOffsetRB.x, -1f + mOffsetRB.y, 0f));
		verts.Add(new Vector3(0f - mOffsetLB.x, -1f + mOffsetLB.y, 0f));
		verts.Add(new Vector3(0f - mOffsetLT.x, mOffsetLT.y, 0f));
	}

